const $=s=>document.querySelector(s),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const key='agenct-chat-v2';let data,person='Alice';try{data=JSON.parse(localStorage.getItem(key))||ChatHub.seed();if(!data.rooms?.Alice||!data.rooms?.Bob||!Array.isArray(data.tasks))data=ChatHub.seed();}catch{data=ChatHub.seed();}function save(){try{localStorage.setItem(key,JSON.stringify(data));}catch{toast('存储不可用，刷新后可能丢失');}}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.t);window.t=setTimeout(()=>$('#toast').style.display='none',3500);}function button(a,label){return `<button class="${['accept','verify','approve','publish'].includes(a)?'primary':'secondary'}" data-action="${a}">${label}</button>`;}
function card(t){let controls='';if(person===t.owner){if(t.status==='awaiting')controls=button('accept','确认接单');if(t.status==='working')controls=button('publish','推进模拟执行')+button('fail','模拟 CI 失败');if(t.status==='verifying')controls=button('verify','推进独立核验');if(t.status==='failed')controls=button('retry','重新尝试');}if(person===t.requester&&t.status==='ready')controls=button('approve','验收通过')+button('return','退回修改');if(!['completed','canceled'].includes(t.status))controls+=button('cancel','取消');return `<div class="task-card" data-task="${t.id}"><div class="task-top"><span>${t.id} · habitat-demo</span><span class="tag">${status(t)}</span></div><h3>${escape(t.title)}</h3><div class="task-info">${t.requester} 委派 → ${t.owner} 负责 · attempt ${t.attempt}<br>只交付待审查 MR · 不合并、不发布${t.head?'<br>模拟 SHA：'+escape(t.head):''}${t.verified?'<br>✓ 当前 SHA 模拟核验通过':''}</div>${controls?'<div class="task-actions">'+controls+'</div>':''}${t.status==='completed'?'<div class="done">✓ 已验收归档，未合并代码</div>':''}</div>`;}
function status(t){return t.status==='ready'?(person===t.requester?'需要你验收':'等派活人验收'):t.status==='awaiting'?(person===t.owner?'需要你接单':'等对方接单'):ChatHub.labels[t.status];}
function render(){save();$('#butler').textContent=person+'的管家';let room=data.rooms[person];let last={};room.forEach((m,i)=>{if(m.taskId)last[m.taskId]=i;});$('#messages').innerHTML=room.map((m,i)=>`<div class="message ${m.kind}">${m.kind==='user'?'':'<div class="mini-avatar">✳</div>'}<div class="bubble">${m.kind==='user'?'':`<div class="meta">${person}的管家 · ${new Date(m.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</div>`}${escape(m.text)}${m.taskId&&last[m.taskId]===i?card(data.tasks.find(t=>t.id===m.taskId)):''}</div></div>`).join('');const active=data.tasks.filter(t=>[t.owner,t.requester].includes(person)&&!['completed','canceled'].includes(t.status));$('#count').textContent='('+active.length+')';$('#focus').innerHTML=active.map(t=>`<button class="focus-item" data-focus="${t.id}"><small>${t.id} · ${t.owner===person?'我负责的':'我委派的'}</small><b>${escape(t.title)}</b><span>${status(t)}</span></button>`).join('')||'<div class="empty">暂时没有需要关注的事。<br>把一个目标交给我吧。</div>';const other=person==='Alice'?'Bob':'Alice';$('#suggestions').innerHTML=[`请${other}修复 WUA 报告单位显示，并补测试`,'查看任务进度','这条是私人备注，不要转发'].map(x=>`<button data-suggest="${escape(x)}">${escape(x)}</button>`).join('');document.querySelectorAll('[data-suggest]').forEach(b=>b.onclick=()=>submit(b.dataset.suggest));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{try{ChatHub.action(data,person,b.closest('[data-task]').dataset.task,b.dataset.action);render();scroll();}catch(e){toast(e.message);}});document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{const el=document.querySelector(`[data-task="${b.dataset.focus}"]`);el?.scrollIntoView({behavior:'smooth',block:'center'});if(innerWidth<1200)$('#context').classList.remove('open');});}
function scroll(){$('#chat-scroll').scrollTop=$('#chat-scroll').scrollHeight;}function submit(text){try{ChatHub.send(data,person,text);$('#input').value='';render();scroll();}catch(e){toast(e.message);}}$('#composer').onsubmit=e=>{e.preventDefault();submit($('#input').value);};$('#input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();submit($('#input').value);}};$('#person').onchange=e=>{person=e.target.value;$('#input').value='';render();scroll();};function drawer(title,html){$('#drawer-title').textContent=title;$('#drawer-body').innerHTML=html;$('#drawer').showModal();}$('#drawer-close').onclick=()=>$('#drawer').close();$('#network').onclick=()=>drawer('底层通信 · 演示观察视角','<p>这里只展示跨管家共享的任务信封摘要，不展示双方私人聊天。此页为本浏览器的模拟观察工具，不是真实权限系统。</p>'+ (data.events.map(e=>`<div class="event"><small>${e.taskId} · ${new Date(e.at).toLocaleTimeString()}</small><b>${escape(e.from)} → ${escape(e.to)}</b><span>${escape(e.text)}</span></div>`).join('')||'<p>尚未发生跨管家通信。试试向另一位成员委派任务。</p>'));$('#privacy').onclick=()=>drawer('隐私与演示边界','<h3>每个人只有一个主窗口</h3><p>各自的管家整理任务、联系协作者、汇总结果。双方可见任务摘要与交付状态，但私人消息不会被复制到对方会话或跨管家事件中。</p><h3>这不是生产系统</h3><p>当前是脚本驱动的浏览器演示，不是真实 AI。两位角色的数据都在同一个浏览器 localStorage；切换视角只是方便体验，不构成登录、权限认证或真实隐私隔离。没有服务器、多用户同步、GitLab、DSH 或模型 API。不要输入敏感信息或凭据。</p><h3>生产版本必须补齐</h3><p>服务端身份认证、私有会话隔离、经授权的任务信封、受控发布与独立核验、持久化和审计。演示中的执行与 CI 均由点击按钮推进，不会在后台真正工作。</p>');$('#context-toggle').onclick=()=>{if(innerWidth<1200)$('#context').classList.toggle('open');else $('#context').classList.toggle('hidden');};$('#context-close').onclick=()=>{if(innerWidth<1200)$('#context').classList.remove('open');else $('#context').classList.add('hidden');};$('#reset').onclick=()=>drawer('重置本地演示','<p>只清除此浏览器的新聊天演示记录，不影响真实外部数据。确定重置吗？</p><button class="primary" id="confirm-reset">确认重置</button>');$('#drawer-body').onclick=e=>{if(e.target.id==='confirm-reset'){data=ChatHub.seed();$('#drawer').close();render();toast('已重置演示');}};$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({demo:true,...data},null,2)],{type:'application/json'}));a.download='agenct-chat-demo.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};render();
